// packages/data/repositories/unidades.js
import { BaseRepository } from './_baseRepo.js';
export class UnidadesRepository extends BaseRepository {
    constructor(db) {
        super(db, 'unidades', { defaultOrderBy: 'nome', filterableColumns: ['funcao', 'hierarquiaID'] });
    }

    isSiglaDuplicada(sigla, excludeId = null) {
        const sql = excludeId
            ? `SELECT 1 FROM unidades WHERE sigla = ? AND id != ? AND excluidoEm IS NULL`
            : `SELECT 1 FROM unidades WHERE sigla = ? AND excluidoEm IS NULL`;
        return !!this.db.prepare(sql).get(excludeId ? [sigla, excludeId] : [sigla]);
    }

    findAllForLookup() {
        return this.db
            .prepare(`SELECT id, sigla, nome FROM unidades
                       WHERE excluidoEm IS NULL ORDER BY sigla`)
            .all();
    }
}
